INSERT INTO public.apartments (agency_id, title, description, photos, bedrooms, bathrooms, max_guests, address, city, country, nightly_rate, cleaning_fee, amenities, status)
SELECT a.id, t.title, t.description, t.photos, t.bedrooms, t.bathrooms, t.max_guests, t.address, t.city, t.country, t.nightly_rate, t.cleaning_fee, t.amenities, t.status
FROM public.agencies a,
(VALUES
  ('Chic Studio near Trevi Fountain','Elegant studio in the heart of Rome, walking distance to all major landmarks.',ARRAY['https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=1200','https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=1200'],1,1,2,'Via del Corso 45','Rome','Italy',140::numeric,30::numeric,ARRAY['wifi','kitchen','air_conditioning','tv','elevator'],'available'),
  ('Modern 3BR Apartment in Eixample','Spacious family apartment with balcony and modernist architecture views.',ARRAY['https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=1200','https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=1200'],3,2,6,'Carrer de Provença 220','Barcelona','Spain',210::numeric,45::numeric,ARRAY['wifi','kitchen','air_conditioning','washer','dryer','balcony','elevator'],'available'),
  ('Bosphorus View Loft','Stunning loft with panoramic Bosphorus views and rooftop access.',ARRAY['https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200','https://images.unsplash.com/photo-1502672023488-70e25813eb80?w=1200'],2,1,4,'Cihangir Mah. 12','Istanbul','Turkey',120::numeric,25::numeric,ARRAY['wifi','kitchen','air_conditioning','tv','balcony'],'booked'),
  ('Cozy Montmartre Hideaway','Charming Parisian apartment steps from Sacré-Cœur with classic zinc rooftops.',ARRAY['https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=1200','https://images.unsplash.com/photo-1522509529254-44a17e00aaa1?w=1200'],1,1,2,'Rue Lepic 78','Paris','France',180::numeric,40::numeric,ARRAY['wifi','kitchen','heating','tv','workspace'],'available'),
  ('Lisbon Riverside Penthouse','Top-floor penthouse with Tagus river views and private terrace.',ARRAY['https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=1200','https://images.unsplash.com/photo-1484154218962-a197022b5858?w=1200'],3,2,5,'Rua da Boavista 100','Lisbon','Portugal',230::numeric,50::numeric,ARRAY['wifi','kitchen','air_conditioning','washer','tv','balcony','elevator','workspace'],'maintenance')
) AS t(title,description,photos,bedrooms,bathrooms,max_guests,address,city,country,nightly_rate,cleaning_fee,amenities,status)
WHERE a.slug = 'sahara-tours';